#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#define N 32
typedef struct {uint8_t world[N][N]; float x,y,a; int screen,sel,mode,stock; bool quit,back,chord; FuriMessageQueue* q; FuriMutex* lock;} Game;
static void str(Canvas*c,int x,int y,const char*s){canvas_draw_str(c,x,y,s);}
static void generate(Game*g){for(int y=0;y<N;y++)for(int x=0;x<N;x++)g->world[y][x]=(x==0||y==0||x==N-1||y==N-1)?1:((rand()%9)==0?1:0);g->x=3.5f;g->y=3.5f;g->world[3][3]=0;g->stock=8;g->a=0;}
static int cell(Game*g,float x,float y){if(x<0||y<0||x>=N||y>=N)return 1;return g->world[(int)y][(int)x];}
static void draw(Canvas*c,void*ctx){Game*g=ctx;if(furi_mutex_acquire(g->lock,0)!=FuriStatusOk)return;canvas_clear(c);canvas_set_font(c,FontSecondary);
if(g->screen==0){str(c,20,9,"MINECRAFT");str(c,2,20,"UP/DOWN: MOVE");str(c,2,30,"LEFT/RIGHT: TURN");str(c,2,40,"OK: BREAK");str(c,2,50,"BACK+OK: BUILD");str(c,2,62,"OK: NEXT");}
else if(g->screen==1){str(c,20,10,"MINECRAFT");const char*items[]={"Survival","Creative","Continue","Controls","Exit"};for(int i=0;i<5;i++){if(i==g->sel)str(c,3,21+i*10,">");str(c,15,21+i*10,items[i]);}}
else {float dx=cosf(g->a),dy=sinf(g->a);for(int x=0;x<128;x+=2){float off=(x-64)/64.f,rx=dx-dy*off,ry=dy+dx*off,d=.05f;while(d<14&&!cell(g,g->x+rx*d,g->y+ry*d))d+=.12f;if(d>=14)continue;int h=(int)(42/d);if(h>64)h=64;int top=32-h/2;canvas_draw_line(c,x,top,x,top+h);if(((int)((g->x+rx*d)*8)+(int)((g->y+ry*d)*8))%3)canvas_draw_line(c,x+1,top,x+1,top+h);canvas_set_color(c,ColorWhite);canvas_draw_dot(c,x,32);canvas_set_color(c,ColorBlack);}canvas_draw_line(c,60,32,68,32);canvas_draw_line(c,64,28,64,36);canvas_draw_box(c,108,46,20,18);canvas_set_color(c,ColorWhite);canvas_draw_frame(c,110,48,16,14);canvas_set_color(c,ColorBlack);canvas_draw_frame(c,35,52,58,12);char buf[24];snprintf(buf,sizeof(buf),g->mode?"BLOCK: INF":"BLOCK: %d",g->stock);str(c,38,61,buf);}
furi_mutex_release(g->lock);}
static void input(InputEvent*e,void*ctx){Game*g=ctx;furi_message_queue_put(g->q,e,0);}
static void edit(Game*g,bool place){float dx=cosf(g->a),dy=sinf(g->a);int px=(int)g->x,py=(int)g->y;for(float d=.1f;d<4;d+=.1f){int x=(int)(g->x+dx*d),y=(int)(g->y+dy*d);if(x<=0||y<=0||x>=N-1||y>=N-1)return;if(g->world[y][x]){if(place){if((px!=(int)g->x||py!=(int)g->y)&&(g->mode||g->stock>0)){g->world[py][px]=1;if(!g->mode)g->stock--;}}else{g->world[y][x]=0;if(!g->mode)g->stock++;}return;}px=x;py=y;}}
int32_t minecraft_main(void*p){UNUSED(p);Game*g=calloc(1,sizeof(Game));if(!g)return -1;generate(g);g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort*v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui*gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;furi_mutex_acquire(g->lock,FuriWaitForever);while(furi_message_queue_get(g->q,&e,0)==FuriStatusOk){if(e.key==InputKeyBack&&e.type==InputTypePress){g->back=true;g->chord=false;}if(e.key==InputKeyBack&&e.type==InputTypeRelease){if(!g->chord&&g->screen==2)g->screen=1;g->back=false;}if(e.type!=InputTypeShort&&e.type!=InputTypeRepeat)continue;if(g->screen==0){if(e.key==InputKeyOk)g->screen=1;}else if(g->screen==1){if(e.key==InputKeyUp)g->sel=(g->sel+4)%5;if(e.key==InputKeyDown)g->sel=(g->sel+1)%5;if(e.key==InputKeyOk){if(g->sel==4)g->quit=true;else if(g->sel==3)g->screen=0;else{if(g->sel<2){g->mode=g->sel;generate(g);}g->screen=2;}}}else{if(e.key==InputKeyOk){edit(g,g->back);if(g->back)g->chord=true;}if(e.key==InputKeyLeft)g->a-=.12f;if(e.key==InputKeyRight)g->a+=.12f;if(e.key==InputKeyUp||e.key==InputKeyDown){float d=e.key==InputKeyUp?.2f:-.2f;float x=g->x+cosf(g->a)*d,y=g->y+sinf(g->a)*d;if(!cell(g,x,g->y))g->x=x;if(!cell(g,g->x,y))g->y=y;}}}furi_mutex_release(g->lock);view_port_update(v);furi_delay_ms(33);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}